glsl3.vert:
precision highp float;
layout(std140) uniform CCGlobal {
  highp   vec4 cc_time;
  mediump vec4 cc_screenSize;
  mediump vec4 cc_nativeSize;
  mediump vec4 cc_probeInfo;
  mediump vec4 cc_debug_view_mode;
};
layout(std140) uniform CCCamera {
  highp   mat4 cc_matView;
  highp   mat4 cc_matViewInv;
  highp   mat4 cc_matProj;
  highp   mat4 cc_matProjInv;
  highp   mat4 cc_matViewProj;
  highp   mat4 cc_matViewProjInv;
  highp   vec4 cc_cameraPos;
  mediump vec4 cc_surfaceTransform;
  mediump vec4 cc_screenScale;
  mediump vec4 cc_exposure;
  mediump vec4 cc_mainLitDir;
  mediump vec4 cc_mainLitColor;
  mediump vec4 cc_ambientSky;
  mediump vec4 cc_ambientGround;
  mediump vec4 cc_fogColor;
  mediump vec4 cc_fogBase;
  mediump vec4 cc_fogAdd;
  mediump vec4 cc_nearFar;
  mediump vec4 cc_viewPort;
};
#if USE_LOCAL
  layout(std140) uniform CCLocal {
    highp mat4 cc_matWorld;
    highp mat4 cc_matWorldIT;
    highp vec4 cc_lightingMapUVParam;
    highp vec4 cc_localShadowBias;
    highp vec4 cc_reflectionProbeData1;
    highp vec4 cc_reflectionProbeData2;
    highp vec4 cc_reflectionProbeBlendData1;
    highp vec4 cc_reflectionProbeBlendData2;
  };
#endif
in vec3 a_position;
in vec2 a_texCoord;
in vec4 a_color;
out vec4 color;
out vec2 uv0;
vec4 vert () {
  vec4 pos = vec4(a_position, 1);
  #if USE_LOCAL
    pos = cc_matWorld * pos;
  #endif
  pos = cc_matViewProj * pos;
  uv0 = a_texCoord;
  color = a_color;
  return pos;
}
void main() { gl_Position = vert(); }

glsl3.frag:
precision highp float;
layout(std140) uniform CCGlobal {
  highp   vec4 cc_time;
  mediump vec4 cc_screenSize;
  mediump vec4 cc_nativeSize;
  mediump vec4 cc_probeInfo;
  mediump vec4 cc_debug_view_mode;
};
layout(std140) uniform CCCamera {
  highp   mat4 cc_matView;
  highp   mat4 cc_matViewInv;
  highp   mat4 cc_matProj;
  highp   mat4 cc_matProjInv;
  highp   mat4 cc_matViewProj;
  highp   mat4 cc_matViewProjInv;
  highp   vec4 cc_cameraPos;
  mediump vec4 cc_surfaceTransform;
  mediump vec4 cc_screenScale;
  mediump vec4 cc_exposure;
  mediump vec4 cc_mainLitDir;
  mediump vec4 cc_mainLitColor;
  mediump vec4 cc_ambientSky;
  mediump vec4 cc_ambientGround;
  mediump vec4 cc_fogColor;
  mediump vec4 cc_fogBase;
  mediump vec4 cc_fogAdd;
  mediump vec4 cc_nearFar;
  mediump vec4 cc_viewPort;
};
in vec4 color;
in vec2 uv0;
layout(std140) uniform Constant { vec4 tint; };
#define TAU 6.28318530718
float hash21(vec2 p){ p=fract(p*vec2(123.34,456.21)); p+=dot(p,p+45.32); return fract(p.x*p.y); }
float vnoise(vec2 p){ vec2 i=floor(p),f=fract(p); vec2 u=f*f*(3.0-2.0*f);
  return mix(mix(hash21(i),hash21(i+vec2(1,0)),u.x),mix(hash21(i+vec2(0,1)),hash21(i+vec2(1,1)),u.x),u.y); }
float fbm(vec2 p){ float v=0.0,a=0.5; for(int i=0;i<5;i++){v+=a*vnoise(p);p*=2.0;a*=0.5;} return v; }
vec3 ACES(vec3 x){ const float a=2.51,b=0.03,c=2.43,d=0.59,e=0.14; return clamp((x*(a*x+b))/(x*(c*x+d)+e),0.0,1.0); }
vec4 frag () {
  vec2 q = uv0*2.0 - 1.0;
  q.y *= 1.779;
  float t = cc_time.x;
  vec2 w = q*1.4;
  w += 0.65*vec2(fbm(q*1.1 + t*0.05), fbm(q*1.1 + 4.0 - t*0.04));
  float n = fbm(w + t*0.03);
  vec3 deep = vec3(0.16,0.10,0.25);
  vec3 mid  = vec3(0.52,0.33,0.72);
  vec3 pink = vec3(0.98,0.62,0.86);
  vec3 col = mix(deep, mid, smoothstep(0.08,0.66,n));
  col = mix(col, pink, smoothstep(0.55,0.92,n)*0.60);
  vec2 pc = vec2(0.45*sin(t*0.08), -0.35 + 0.2*sin(t*0.06));
  col += pink * 0.20 * smoothstep(1.25, 0.0, length(q - pc));
  col += mid  * 0.12 * smoothstep(1.10, 0.0, length(q - vec2(-0.3, 0.7)));
  col += pink * smoothstep(0.50,0.0, abs(dot(q,normalize(vec2(0.7,1.0))) - sin(t*0.15)*0.85)) * 0.14;
  col += mid  * smoothstep(0.60,0.0, abs(dot(q,normalize(vec2(-0.5,1.0))) - sin(t*0.10+2.0)*0.95)) * 0.10;
  vec2 cell = floor(q*7.0);
  vec2 jit = vec2(hash21(cell), hash21(cell+3.1)) - 0.5;
  vec2 g = fract(q*7.0) - 0.5 - jit*0.7;
  col += vec3(1.0,0.92,1.0) * smoothstep(0.06,0.0,length(g)) * (0.4+0.6*sin(t*3.0+hash21(cell)*TAU)) * 0.16;
  col *= smoothstep(2.15, 0.5, length(q));
  col = ACES(col*1.25) * tint.rgb;
  return vec4(col, 1.0);
}
layout(location = 0) out vec4 cc_FragColor;
void main() { cc_FragColor = frag(); }

